<script setup lang="ts">
import{ref,computed,watch,onMounted,onUnmounted}from'vue';import{useReceiptCommand}from'./use-receipt-command';import{useReceiptRead}from'./use-receipt-read';import{RefreshCw,ArrowLeft,X}from'@lucide/vue';import ReceiptAdjustmentPicker from './ReceiptAdjustmentPicker.vue';
const props=defineProps<{staff:any}>(),emit=defineEmits(['unauthorized']);const clinics=ref<any[]>([]),clinic=ref(''),date=ref(''),kind=ref('all'),search=ref(''),pageSize=ref('50'),writing=ref(false),form=ref<any>(null),retryConfirmed=ref(false);
let alive=true;const identity=()=>JSON.stringify([props.staff?.accountId,props.staff?.employeeId]);
const command=useReceiptCommand({owner:()=>props.staff?.accountId&&props.staff?.employeeId?props.staff:null,storage:()=>sessionStorage,read:path=>api(path),send:(id,body)=>api('/'+id+'/correction',body),completed:async id=>{form.value=null;await open(id);}}),{pending,notice,error:commandError}=command;
const reader=useReceiptRead({identity,scope:()=>JSON.stringify([clinic.value,date.value,kind.value,search.value,pageSize.value]),clinic:()=>clinic.value,date:()=>date.value,kind:()=>kind.value,search:()=>search.value.trim(),limit:()=>pageSize.value,read:(path,signal)=>api(path,undefined,signal),invalidated:status=>{form.value=null;if(status===401)emit('unauthorized');}}),{rows,next,summary,total,asOf,detail,history,nextVersion,error}=reader,busy=computed(()=>writing.value||reader.busy.value||command.busy.value);
const methods:Record<string,string>={cash:'现金',card:'银行卡',bank:'银行',wechat:'微信',alipay:'支付宝',other:'其他'},full=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—',local=(s:string)=>new Date(Date.parse(s)+8*3600000).toISOString().slice(0,23),instant=(s:string)=>s?new Date(s+'+08:00').toISOString():'';
class ApiError extends Error{constructor(public status:number,m:string){super(m);}}
async function api(path:string,body?:any,signal?:AbortSignal){const owner=identity(),ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),15000);try{const r=await fetch('/api/v1/receipts'+path,{method:body?'POST':'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined,signal:signal?AbortSignal.any([signal,ctrl.signal]):ctrl.signal}),b=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401&&alive&&owner===identity())emit('unauthorized');throw new ApiError(r.status,b.message||'实收核实失败。');}return b;}finally{clearTimeout(timer);}}
const explain=(e:any)=>e instanceof Error?e.message:'操作失败。';
async function load(more=false){return reader.load(more);}async function open(id:string,more=false){if(!more)form.value=null;return reader.open(id,more);}
function correct(){if(pending.value||command.isBlocked()||!detail.value?.canCorrect)return;const d=detail.value;form.value={receivedAt:local(d.receivedAt),paymentMethod:d.method,basis:d.basis,reason:'',actualConfirmed:false,adjustmentIds:[]};error.value='';}
async function send(body:any,id:string,retry=false){const owner=identity();retryConfirmed.value=false;const saved=retry?await command.retry():await command.submit(id,body);if(alive&&owner===identity()&&(saved||pending.value))form.value=null;}
async function retryOriginal(){if(!retryConfirmed.value||command.status.value?.state!=='not_found')return;await send(null,'',true);}
async function save(){try{const f=form.value;await send({...f,receivedAt:instant(f.receivedAt),requestId:crypto.randomUUID(),version:detail.value.version},detail.value.id);}catch(e){error.value=explain(e);}}
async function initialize(){const owner=identity();writing.value=true;try{command.restore();const b=await api('/bootstrap');if(!alive||owner!==identity())return;clinics.value=b.clinics;clinic.value=clinics.value[0]?.id||'';date.value=b.today;await load();}catch(e){if(alive&&owner===identity())error.value=explain(e);}finally{if(alive&&owner===identity())writing.value=false;}}
watch(identity,()=>{form.value=null;retryConfirmed.value=false;clinics.value=[];writing.value=false;},{flush:'sync'});onUnmounted(()=>{alive=false;});
async function refresh(){if(writing.value||form.value||pending.value)return;if(detail.value)await open(detail.value.id);else await load();}onMounted(initialize);defineExpose({refresh});
</script>
<template><div class="receipt-workspace"><div v-if="error" class="b-alert error" role="alert">{{error}}</div><div v-if="notice" class="b-alert success" role="status">{{notice}}</div><div v-if="commandError" class="b-alert error" role="alert">{{commandError}}</div><section v-if="pending" class="b-alert warning"><strong>{{pending.summary}}</strong><template v-if="pending.phase==='pending'"><p>原更正结果不明。请先只读核实原请求，不要另填一笔。</p><button class="b-button outline" :disabled="busy" @click="retryConfirmed=false;command.verify()">只读核实原更正</button><div v-if="command.status.value?.state==='completed'"><p>查到原更正：第{{command.status.value.version}}版，保存时间{{full(command.status.value.completedAt)}}。此结果对应原请求，不保证当前表单或后来的收款状态。</p><button class="b-button outline" :disabled="busy" @click="command.acknowledge()">已核对原结果，仅清理提示</button></div><p v-else-if="command.status.value?.state==='not_found'">本次未见成功记录，可能仍在处理或未提交；查询不会补写，也不会自动重试。</p><label v-if="command.status.value?.state==='not_found'" class="b-checkbox"><input type="checkbox" v-model="retryConfirmed" :disabled="busy"/><span>已核对原收款，确认按原请求编号及原内容重试</span></label><button v-if="command.status.value?.state==='not_found'" class="b-button outline" :disabled="busy||!retryConfirmed" @click="retryOriginal">按原请求重试更正</button></template><template v-else><p>{{pending.phase==='confirmed'?'业务已经成功，仅本机提示尚未清理。':'原更正已被拒绝，仅本机提示尚未清理。'}}</p><button class="b-button outline" :disabled="busy" @click="command.cleanup()">仅清理本机提示</button></template></section>
 <template v-if="!detail"><section class="b-card rc-block"><h2>实收核实与更正</h2><p>按实际到账日期检索治疗与商品实收，逐条核实已发生事实。</p><div class="rc-filters"><label>收款诊所<select v-model="clinic" :disabled="busy||!!pending" @change="load()"><option v-for="c in clinics" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>实际到账日期<input type="date" v-model="date" :disabled="busy||!!pending" @change="load()"/></label><label>单据类别<select v-model="kind" :disabled="busy||!!pending" @change="load()"><option value="all">全部有权类别</option><option v-for="k in clinics.find(c=>c.id===clinic)?.kinds||[]" :value="k" :key="k">{{k==='bill'?'治疗账单':'商品销售单'}}</option></select></label><label>患者姓名<input v-model="search" :disabled="busy||!!pending" maxlength="100" placeholder="输入后点击查询" @keydown.enter.prevent="load()"/></label><label>每页实收<select v-model="pageSize" :disabled="busy||!!pending" @change="load()"><option value="10">10</option><option value="25">25</option><option value="50">50</option></select></label><button class="b-button outline" :disabled="busy" @click="load()"><RefreshCw :size="16"/>查询</button></div><p v-if="summary">已显示{{rows.length}} / {{total}}份 · 读取时点{{full(asOf)}}。姓名与日期范围内全部有权类别：共{{summary.total}}份、{{summary.amount}}元；治疗{{summary.bills}}份、{{summary.billAmount}}元，商品{{summary.sales}}份、{{summary.saleAmount}}元。统计覆盖完整范围，不随当前页或单据类别缩小。</p><p v-else>填写或调整条件后点击查询；统计在读取完成后显示。</p></section><section class="b-card rc-block"><div class="q-table-wrap"><table><thead><tr><th>患者 / 单据</th><th>实收金额</th><th>实际到账</th><th>版本</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.patientName}}<small>{{r.kind==='bill'?'治疗账单':'商品销售单'}} · {{r.id.slice(0,8).toUpperCase()}}</small></td><td>{{r.amount}}元</td><td>{{full(r.receivedAt)}}</td><td>{{r.version}}</td><td><button class="b-button outline small" :disabled="busy" @click="open(r.id)">核实原记录</button></td></tr><tr v-if="!rows.length"><td colspan="5">{{busy?'正在读取…':'所选范围没有实收记录。'}}</td></tr></tbody></table></div><button v-if="next" class="b-button outline" :disabled="busy" @click="load(true)">加载后续实收</button></section></template>
 <template v-else><button class="b-button outline small" :disabled="busy||!!pending" @click="detail=null;load()"><ArrowLeft :size="16"/>返回实收列表</button><section class="b-card rc-block"><div class="rc-heading"><div><h2>{{detail.patientName}} · {{detail.kind==='bill'?'治疗实收':'商品实收'}}</h2><p>收款{{detail.id.slice(0,8).toUpperCase()}} · 当前第{{detail.version}}版</p></div><strong class="rc-amount">{{detail.amount}}元</strong></div><p>付款方式：{{methods[detail.method]}}<br/>实际到账：{{full(detail.receivedAt)}}<br/>首次登记：{{full(detail.registeredAt)}}</p><p>核实依据：{{detail.basis}}</p><button v-if="detail.canCorrect" class="b-button" :disabled="busy||!!pending||command.isBlocked()" @click="correct">核实并更正到账记录</button><p class="b-help">金额、原单据及首次登记资料固定。更正实际到账或方式时，保留原版并衔接受影响季度另版核算。</p></section><section class="b-card rc-block"><h2>逐版核实历史</h2><p>当前核对第{{reader.historyVersion.value}}版收款；后续页若发现新更正，会要求重新打开，避免混合版本。</p><article v-for="h in history" :key="h.id" class="rc-history"><strong>第{{h.version}}版 · {{h.amount}}元 · {{methods[h.method]}}</strong><p>实际到账 {{full(h.receivedAt)}}<br/>本版登记 {{full(h.recordedAt)}} · {{h.recordedBy}}<br/>首次登记 {{full(h.registeredAt)}}</p><p>依据：{{h.basis}}<br/>本次原因：{{h.reason||'首次登记依据见上'}}</p><small>采用原单据版本：{{h.billRevisionId||h.saleRevisionId}}</small></article><button v-if="nextVersion" class="b-button outline" :disabled="busy" @click="open(detail.id,true)">加载更早原版</button></section></template>
 <div v-if="form" class="b-backdrop"><form class="b-dialog rc-dialog" role="dialog" aria-modal="true" @submit.prevent="save"><button type="button" class="b-close" aria-label="关闭实收更正" :disabled="busy||!!pending" @click="form=null"><X :size="20"/></button><h2>核实并更正实收</h2><p>{{detail.patientName}} · 原实收{{detail.amount}}元 · 第{{detail.version}}版</p><label>经核实的实际到账时间（北京时间）<input type="datetime-local" step="0.001" v-model="form.receivedAt" :disabled="busy||!!pending" required/></label><label>经核实的付款方式<select v-model="form.paymentMethod" :disabled="busy||!!pending" required><option v-for="(m,k) in methods" :key="k" :value="k">{{m}}</option></select></label><label>实际收款核实依据<textarea v-model="form.basis" :disabled="busy||!!pending" required maxlength="1500" rows="2"/></label><label>本次更正原因<textarea v-model="form.reason" :disabled="busy||!!pending" required maxlength="1500" rows="2"/></label><ReceiptAdjustmentPicker v-model="form.adjustmentIds" :clinic-id="detail.clinicId" :kind="detail.kind" :received-at="instant(form.receivedAt)" :receipt-id="detail.id" :disabled="busy||!!pending"/><label class="b-checkbox"><input type="checkbox" v-model="form.actualConfirmed" :disabled="busy||!!pending" required/><span>已核实真实收款事实、本次更正内容和受影响季度；原金额与单据保持。</span></label><div v-if="error" class="b-alert error" role="alert">{{error}}</div><button class="b-button full" :disabled="busy">{{busy?'正在保存…':'确认保存核实更正'}}</button></form></div>
</div></template>
<style scoped>.rc-block{padding:26px;margin:20px 0}.rc-block h2{font-size:21px;margin:0 0 12px}.rc-block p,.rc-dialog p{font-size:14px;line-height:1.8;color:#758374;overflow-wrap:anywhere}.rc-filters{display:flex;gap:16px;align-items:end;flex-wrap:wrap}.rc-filters label{flex:1;min-width:180px}.rc-heading{display:flex;align-items:center;justify-content:space-between;gap:20px}.rc-amount{font-size:26px;color:#345a47}.rc-history{padding:18px 0;border-bottom:1px solid #e3e8df;overflow-wrap:anywhere}.rc-history small,td small{display:block;color:#7c8d78;font-size:12px;margin-top:6px}.rc-dialog{max-width:720px;max-height:90vh;overflow:auto}@media(max-width:760px){.rc-block{padding:18px}.rc-filters{flex-direction:column;align-items:stretch}.rc-heading{align-items:start;flex-direction:column}}</style>
